const GROUPS={ganga:"Ganga system",indus:"Indus system",brahmaputra:"Brahmaputra system",east:"East-flowing Peninsular",west:"West-flowing Peninsular",godavari:"Godavari system",narmada:"Narmada system",range:"Mountain & hill ranges",peak:"Mountain peaks",pass:"Passes & gaps"};
const $=id=>document.getElementById(id);
