const state={setupCount:10,setupTimed:false,setupSeconds:30,sessionRegionChosen:false,sessionFeatures:[],rivers:[],places:[],states:[],cities:[],selectedCity:null,cityStateContext:null,catalog:true,topic:"rivers",topicQuery:"",stateSelected:null,latitudes:false,stateBorders:true,indiaCountryBorders:true,worldBorders:true,sidebarWidth:null,sidebarResize:null,land:[],worldLand:[],worldPlaces:[],worldTopic:"countries",worldCatalog:true,worldContinent:false,worldTopicQuery:"",edits:{},editTarget:null,originals:{},worldFeatureSelected:null,southQuery:"",southGroup:"all",worldQuery:"",worldRegion:"all",worldSelected:null,worldSidebar:false,indiaSidebar:false,worldLayers:false,indiaLayers:false,scope:"india",mode:"explore",group:"all",query:"",selected:null,detail:false,labels:true,session:null,history:{},timer:null,view:{x:0,y:0,w:1000,h:900},drag:null,storageOK:true};
const shuffle=values=>{const a=[...values];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const xy=([lon,lat])=>[(lon-61)*23.4,(39.5-lat)*26];
const linePath=line=>line.map((p,i)=>(i?"L":"M")+xy(p).map(v=>v.toFixed(2)).join(",")).join("");
const riverPath=r=>r.lines.map(linePath).join("");
const indiaShapeCache=new WeakMap(),worldShapeCache=new WeakMap();
function countryPath(geometry){if(indiaShapeCache.has(geometry))return indiaShapeCache.get(geometry);const polygons=geometry.type==="Polygon"?[geometry.coordinates]:geometry.coordinates;const path=polygons.map(p=>p.map(ring=>linePath(ring)+"Z").join("")).join("");indiaShapeCache.set(geometry,path);return path;}
const river=id=>[...state.rivers,...state.places,...worldItems()].find(r=>r.id===id);
