function renderDetail(){const r=river(state.selected);if(!r){state.detail=false;renderList();return;}
 $("sidebar-content").innerHTML=`<article class="detail"><button class="back-link" data-action="back">← All matching rivers</button><h2>${esc(r.name)}</h2><p class="detail-group">${esc(GROUPS[r.group])}</p><dl><div class="fact"><dt>${r.kind==="point"?"Location":"Source"}</dt><dd>${esc(r.source)}</dd></div><div class="fact"><dt>${r.kind==="point"?"Feature type":"Joins / drains into"}</dt><dd>${esc(r.mouth)}</dd></div><div class="fact"><dt>Course at a glance</dt><dd>${esc(r.route)}</dd></div></dl><div class="note"><p class="eyebrow">MAKE THE CONNECTION</p>${esc(r.note)}</div>${r.kind==="point"?`<p class="coordinate-note">Approximate ${r.group==="range"?"representative range":"location"} marker · <a href="${esc(r.coordinateSource)}" target="_blank" rel="noopener">Coordinate source ↗</a></p>`:renderTributaries(r)}<button class="edit-place-button" data-edit="${esc(r.id)}">✎ Edit information</button><div class="detail-actions"><button class="secondary" data-action="focus">⌖ Focus river</button><button class="primary" data-action="practice-group">Practise this group</button></div></article>`;
}
function groupOptions(){const keys=state.topic==='mountains'?['range','peak','pass']:['ganga','indus','brahmaputra','godavari','narmada','east','west'];return '<option value="all">All places · '+activeItems().length+'</option>'+keys.map(key=>`<option value="${key}"${state.group===key?' selected':''}>${GROUPS[key]}</option>`).join('');}
function sessionFeatureOptions(){return [...new Set(worldPool().map(p=>p.group))].map(group=>({group,name:group==='country'?'Countries':group==='political'?'Territories':WORLD_GROUPS[group]||group,count:worldPool().filter(p=>p.group===group).length}));}
function chooseSessionRegion(region){if(region!=='all'&&!worldItems().some(p=>p.region===region))return;state.worldRegion=region;state.sessionRegionChosen=true;state.group='all';state.sessionFeatures=sessionFeatureOptions().map(o=>o.group);renderSidebar();$('session-region')?.focus?.({preventScroll:true});}
function sessionPool(){const pool=activeItems().filter(matchesGroup);if(state.scope==='world'&&state.worldTopic==='all'){if(!state.sessionRegionChosen)return [];return pool.filter(p=>state.sessionFeatures.includes(p.group));}return pool;}
function sessionRegionMarkup(){const regions=[...new Set(worldItems().map(p=>p.region))].sort();return '<label class="filter-label" for="session-region">REGION</label><select id="session-region"><option value="" '+(!state.sessionRegionChosen?'selected':'')+' disabled>Choose a region</option><option value="all" '+(state.sessionRegionChosen&&state.worldRegion==='all'?'selected':'')+'>All regions</option>'+regions.map(region=>'<option value="'+esc(region)+'" '+(state.sessionRegionChosen&&region===state.worldRegion?'selected':'')+'>'+esc(region)+'</option>').join('')+'</select>';}
function questionCount(available, requested = state.setupCount) {
 const count = Number(requested);
 return Math.min(available, Number.isFinite(count) && count > 0 ? Math.max(1, Math.floor(count)) : state.setupCount);
}
function sessionStartLabel(count) {
 return count ? 'Start ' + count + '-place ' + state.mode + ' →' : 'Choose places to begin';
}
document.addEventListener('input', event => {
 if (event.target.id !== 'session-count') return;
 const count = Number(event.target.value);
 if (!Number.isInteger(count) || count < 1) return;
 state.setupCount = count;
 const start = document.querySelector('[data-action="start"]');
 if (start) start.textContent = sessionStartLabel(questionCount(sessionPool().length));
});
document.addEventListener('change', event => {
 if (event.target.id === 'session-count') event.target.value = questionCount(sessionPool().length);
});
function renderSetup(){
 const world=state.scope==='world',allWorld=world&&state.worldTopic==='all',available=sessionPool().length,total=questionCount(available);
 let filters='';
 if(allWorld){filters=state.worldContinent?'<p class="session-region-label">Region: '+esc(state.worldRegion)+'</p>':sessionRegionMarkup();
  if(state.sessionRegionChosen){const options=sessionFeatureOptions(),all=options.length&&options.every(o=>state.sessionFeatures.includes(o.group));filters+='<fieldset class="session-features"><legend>Features</legend><label class="session-feature-all"><input id="session-features-all" type="checkbox" '+(all?'checked':'')+'> All features</label>'+options.map(o=>'<label><input type="checkbox" data-session-feature="'+o.group+'" '+(state.sessionFeatures.includes(o.group)?'checked':'')+'> <span>'+esc(o.name)+'</span><small>'+o.count+'</small></label>').join('')+'</fieldset>';}
 }else filters=(world?worldRegionControl('session-region'):'')+'<label class="filter-label" for="session-system">'+(world?'FEATURE TYPE':'PLACES')+'</label><select id="session-system">'+(world?worldGroupOptions():groupOptions())+'</select>';
 $('sidebar-content').innerHTML='<div class="session-start compact-setup">'+filters+(available?'<label class="filter-label" for="session-count">NUMBER OF QUESTIONS</label><input id="session-count" type="number" min="1" max="'+available+'" step="1" inputmode="numeric" value="'+total+'"><p class="session-count-available">'+available+' available with these filters</p>':'')+'<div class="session-timer-settings"><label class="timer-check"><input id="timer-enabled" type="checkbox" '+(state.setupTimed?'checked':'')+'> Optional timer</label><label class="sr-only" for="timer-duration">Time per place</label><select id="timer-duration" '+(!state.setupTimed?'disabled':'')+'>'+[15,30,60,90,120].map(n=>'<option value="'+n+'" '+(n===state.setupSeconds?'selected':'')+'>'+n+' seconds per place</option>').join('')+'</select></div><button class="primary" data-action="start" '+(!total?'disabled':'')+'>'+sessionStartLabel(total)+'</button></div>';
}
function activeSession(){return !!state.session&&!state.session.done;}
function syncSessionLayout(){const active=activeSession();document.documentElement.dataset.sessionActive=String(active);const s=state.session;document.documentElement.dataset.answerStatus=active&&s.revealed?(s.mode==='practice'?(s.choice===s.ids[s.index]?'correct':'wrong'):'revealed'):'pending';for(const id of ['session-topbar','session-overlay','session-feedback'])$(id).hidden=!active;const sidebar=document.querySelector('.sidebar');if(sidebar)sidebar.inert=active||!(state.scope==='world'?state.worldSidebar:state.indiaSidebar);if(!active){for(const id of ['session-topbar','session-overlay','session-feedback','quiz-marker'])$(id).innerHTML='';}return active;}
function renderWorldSidebar(){if(state.worldCatalog){renderWorldCatalog();return;}if(state.mode!=='explore'){if(!state.session)renderSetup();else if(state.session.done)renderSummary();else renderQuiz();return;}const rows=state.worldQuery.trim()?globalSearch('world',state.worldQuery):worldVisible();$("sidebar-content").innerHTML='<div class="world-sidebar"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="world-place-search" type="search" placeholder="Search places or notes…" aria-label="Search world places" value="'+esc(state.worldQuery)+'"></label><label class="filter-label" for="world-feature-group">FEATURE TYPE</label><select id="world-feature-group">'+worldGroupOptions()+'</select>'+worldRegionControl('world-region')+'<div class="list-heading"><span id="world-list-count">'+rows.length+(state.worldQuery.trim()?' RESULTS':' PLACES')+'</span></div><div id="world-place-list">'+worldPlaceRows()+'</div></div>';}
function worldList(rows){return rows.length?rows.map(c=>`<button class="world-country-row${c.id===state.worldSelected?' active':''}" data-country-select="${esc(c.id)}"><span>${esc(c.name)}</span><small>${esc(c.continent)}</small></button>`).join(''):'<p class="empty">No countries match this search.</p>';}
function renderScope(){const world=state.scope==='world',catalog=world?state.worldCatalog:state.catalog;$("scope-eyebrow").textContent=world?'GEOGRAPHY / WORLD':'GEOGRAPHY / INDIA';$("scope-title").innerHTML=world?(catalog?'World atlas':esc(state.worldContinent?state.worldRegion:WORLD_TOPICS[state.worldTopic]?.name||'World places'))+'<span>.</span>':state.catalog?'India atlas<span>.</span>':state.topic==='mountains'?'Mountains, peaks &amp; passes<span>.</span>':state.topic==='all'?'All India places<span>.</span>':'Rivers &amp; drainage<span>.</span>';$("scope-intro").textContent=catalog?'Explore by topic.':'';$("learning-modes").hidden=catalog;document.querySelectorAll('[data-scope]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scope===state.scope)));}
function renderSidebar(){syncSessionLayout();const world=state.scope==='world';$("explorer-controls").hidden=world||state.mode!=="explore"||state.topic!=="rivers";renderScope();$("topics-back").hidden=world||state.catalog;$("learning-modes").hidden=world||state.catalog;if(world){$("topics-back").hidden=state.worldCatalog;$("topics-back").textContent="← All World topics";$("learning-modes").hidden=state.worldCatalog;document.querySelectorAll("[data-mode]").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.mode===state.mode)));renderWorldSidebar();return;}$("topics-back").textContent="← All India topics";if(state.catalog){$("explorer-controls").hidden=true;renderCatalog();return;}$("system").innerHTML=groupOptions();$("system").value=state.group;$("search").placeholder="Search names, regions or notes…";const exploring=state.mode==='explore';document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===state.mode));if(exploring){if(state.detail)renderDetail();else if(state.topic==='rivers')renderList();else renderPhysicalList();}else if(!state.session)renderSetup();else if(state.session.done)renderSummary();else renderQuiz();}
function stopTimer(){if(state.timer){clearInterval(state.timer);state.timer=null;}}
function setMode(mode){stopTimer();if(state.scope==='india')state.catalog=false;state.mode=mode;state.session=null;state.detail=false;if(state.scope==="world"){state.worldCatalog=false;state.worldSidebar=true;}else state.indiaSidebar=true;updateWorldLayout();renderSidebar();renderMap();}
function setScope(scope){if(!["india","world"].includes(scope)||scope===state.scope)return;cancelViewMotion();const panel=document.querySelector('.map-panel');if(panel?.animate&&!reducedMotion())panel.animate([{opacity:.25},{opacity:1}],{duration:320,easing:'ease-out'});stopTimer();state.selectedCity=null;state.cityStateContext=null;state.scope=scope;if(scope==="world"&&state.worldCatalog)state.worldSidebar=true;state.mode="explore";state.session=null;state.detail=false;state.drag=null;updateWorldLayout();resetMap();if(scope==='world'&&!state.worldCatalog&&state.worldTopic!=='countries'&&state.worldTopic!=='all')fitWorldTopic();renderSidebar();renderMap();announce(scope==="world"?"World map workspace opened.":"India river atlas opened.");}
function startSession(ids){
 stopTimer();if(state.scope==='india')state.catalog=false;const pool=ids?ids.map(river).filter(Boolean):sessionPool();if(!pool.length){announce('Choose a region and at least one feature.');return;}
 const timerEnabled=$('timer-enabled')?.checked??state.setupTimed,seconds=Number($('timer-duration')?.value)||state.setupSeconds;state.setupTimed=timerEnabled;state.setupSeconds=[15,30,60,90,120].includes(seconds)?seconds:30;
 const count = ids ? questionCount(pool.length) : questionCount(pool.length, $('session-count')?.value);
 state.session={mode:state.mode,ids:shuffle(pool.map(p=>p.id)).slice(0,count),poolIds:pool.map(p=>p.id),index:0,revealed:false,done:false,results:[],timed:timerEnabled,limitSeconds:state.setupSeconds,seconds:state.setupSeconds,options:[]};prepareQuestion();
}
function prepareQuestion(){
 const s=state.session,target=river(s.ids[s.index]);s.revealed=false;s.choice=null;s.seconds=s.limitSeconds;s.timedOut=false;
 const fallback=state.scope==='world'?worldItems():activeItems();
 const poolIds=new Set(s.poolIds),pool=fallback.filter(place=>poolIds.has(place.id));
 const seen=new Set([target.name.toLocaleLowerCase()]),decoys=[];
 for(const item of [...shuffle(pool.filter(p=>p.group===target.group)),...shuffle(fallback.filter(p=>p.group===target.group)),...shuffle(pool),...shuffle(fallback)]){const name=item.name.toLocaleLowerCase();if(seen.has(name))continue;seen.add(name);decoys.push(item);if(decoys.length===3)break;}
 s.options=shuffle([target,...decoys]).map(r=>r.id);
 state.selectedCity=null;state.cityStateContext=null;state.stateSelected=null;state.worldSelected=null;state.worldFeatureSelected=null;renderSidebar();resetMap();if(state.scope==='world')focusWorldStudy(target);else focusIndiaFeature(target);renderMap();startTimer();$('quiz-question')?.focus?.({preventScroll:true});
}
function startTimer(){stopTimer();const s=state.session;if(!s?.timed||s.revealed||s.done)return;s.deadline=Date.now()+s.seconds*1000;state.timer=setInterval(updateSessionClock,250);}
function updateSessionClock(){const s=state.session;if(!s?.timed||s.done||s.revealed)return;s.seconds=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));const el=$('seconds');if(el)el.textContent=s.seconds+'s';const progress=$('quiz-timer-progress');if(progress)progress.value=s.seconds;if(s.seconds<=0){s.timedOut=true;if(s.mode==='practice')answer(null);else reveal();announce('Time is up. The answer is revealed.');}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')updateSessionClock();});
function toggleSessionTimer(){const s=state.session;if(!s||s.done||s.revealed)return;s.timed=!s.timed;state.setupTimed=s.timed;s.seconds=s.limitSeconds;renderQuiz();startTimer();}
function quizPrompt(place) {
 const types = {
  country:'country', political:'territory', city:'city', range:'mountain range', peak:'peak',
  pass:'mountain pass', plateau:'plateau', desert:'desert', biome:'biome', island:'island',
  lake:'lake', river:'river', waterfall:'waterfall', dam:'dam', sea:'body of water',
  coast:'coastal feature', resource:'resource site', current:'ocean current',
  tectonic:'tectonic plate', trench:'ocean trench', 'volcanic-belt':'volcanic belt'
 };
 const type = types[place.kind === 'country' ? 'country' : place.kind !== 'point' && state.scope === 'india' ? 'river' : place.group];
 return 'Which ' + (type || 'place') + ' is this?';
}
function renderQuiz(){
 const s=state.session,r=river(s.ids[s.index]),recall=s.mode==='recall';syncSessionLayout();$('sidebar-content').innerHTML='';
 $('session-topbar').innerHTML='<div class="session-back-timer"><button class="quiz-back" data-action="end" aria-label="End session">‹</button><button class="quiz-timer" data-action="toggle-session-timer" aria-label="'+(s.timed?'Turn timer off':'Turn timer on')+'" aria-pressed="'+s.timed+'" '+(s.revealed?'disabled':'')+'><span id="seconds">'+(s.timed?(s.timedOut?'Time up':s.seconds+'s'):'Timer off')+'</span></button></div><div class="session-counter" aria-label="Question '+(s.index+1)+' of '+s.ids.length+'">'+(s.index+1)+' / '+s.ids.length+'</div>';
 $('session-feedback').innerHTML=s.revealed&&!recall?'<strong class="quiz-outcome '+(s.choice===r.id?'correct':'wrong')+'">'+(s.timedOut?'Time up':s.choice===r.id?'Correct':s.choice?'Incorrect':'Skipped')+'</strong>':'';
 const progress='<progress id="quiz-timer-progress" class="session-progress" value="'+(s.timed?s.seconds:s.index+1)+'" max="'+(s.timed?s.limitSeconds:s.ids.length)+'" aria-label="'+(s.timed?'Time remaining':'Session progress')+'"></progress>';
 let body;if(recall){body=!s.revealed?'<button class="recall-reveal" data-action="reveal">Reveal answer</button>':'<div class="recall-revealed"><strong class="recall-name">'+esc(r.name)+'</strong>'+(r.capital?'<span>Capital: '+esc(r.capital)+'</span>':'')+'</div><div class="recall-grading">'+(!s.timedOut?'<button class="recall-known" data-action="known">I knew it ✓</button>':'')+'<button class="recall-again" data-action="again">'+(s.timedOut?'Continue →':'Review again')+'</button></div>';
 }else body='<div class="quiz-options">'+s.options.map(id=>'<button class="answer-option'+(s.revealed?(id===r.id?' correct':id===s.choice?' wrong':''):'')+'" data-answer="'+id+'" '+(s.revealed?'disabled':'')+'>'+esc(river(id).name)+(s.revealed&&id===r.id?' <span aria-hidden="true">✓</span>':'')+'</button>').join('')+'</div><div class="session-actions">'+(s.revealed?'<button class="quiz-next" data-action="next">'+(s.index===s.ids.length-1?'See summary':'Next place →')+'</button>':'<button class="skip-button" data-action="skip">Skip and show answer</button>')+'</div>';
 $('session-overlay').innerHTML=progress+'<h2 id="quiz-question" tabindex="-1">'+quizPrompt(r)+'</h2>'+body;
}
function renderSessionMarker(){
 if(!activeSession()){$('quiz-marker').innerHTML='';return;}const s=state.session,r=river(s.ids[s.index]),[x,y]=(state.scope==='world'?worldXY:xy)(r.label),symbol=s.revealed?(s.mode==='practice'?(s.choice===r.id?'✓':'×'):'✓'):'?';
 $('quiz-marker').innerHTML='<g class="place-marker quiz-pin" data-x="'+x+'" data-y="'+y+'" transform="translate('+x+' '+y+') scale('+markerScale()+')"><path d="M0 0V-20"/><circle class="quiz-pin-base" r="3"/><circle class="quiz-pin-head" cy="-22" r="13"/><text class="quiz-pin-symbol" text-anchor="middle" y="-17">'+symbol+'</text>'+(s.revealed?'<text class="quiz-location-label" text-anchor="middle" y="-43">'+esc(r.name)+'</text>':'')+'</g>';
}
function recordResult(ok,skipped=false){const s=state.session,id=s.ids[s.index];if(s.results.some(r=>r.id===id))return;s.results.push({id,ok,skipped});const old=state.history[id]||{};state.history[id]={seen:(Number(old.seen)||0)+1,correct:(Number(old.correct)||0)+(ok?1:0),review:(Number(old.review)||0)+(ok?0:1),last:Date.now()};saveLocal();}
function answer(id){const s=state.session;if(!s||s.done||s.revealed||s.mode!=='practice'||(id!==null&&!s.options.includes(id)))return;stopTimer();s.choice=id;s.revealed=true;const target=s.ids[s.index];recordResult(id===target,id===null);renderSidebar();renderMap();announce(id===target?'Correct. '+river(target).name:river(target).name+' is the correct answer.');}
function reveal(){const s=state.session;if(!s||s.done||s.revealed||s.mode!=='recall')return;stopTimer();s.revealed=true;renderSidebar();renderMap();announce('The place is '+river(s.ids[s.index]).name);}
function nextQuestion(){const s=state.session;if(!s||s.done||!s.revealed||!s.results.some(r=>r.id===s.ids[s.index]))return;stopTimer();if(s.index===s.ids.length-1){s.done=true;renderSidebar();renderMap();announce('Session complete.');return;}s.index++;prepareQuestion();}
function renderSummary(){const s=state.session,correct=s.results.filter(r=>r.ok).length,skipped=s.results.filter(r=>r.skipped).length,review=s.results.filter(r=>!r.ok).length;
 $("sidebar-content").innerHTML=`<div class="session-summary"><p class="eyebrow">${s.results.length===s.ids.length?'SESSION COMPLETE':'SESSION ENDED'}</p><div class="summary-score">${correct}<small> / ${s.results.length}</small></div><p>${s.mode==='recall'?'Self-rated places recalled':'Places identified correctly'}</p><div class="summary-breakdown"><div><strong class="correct">${correct}</strong><span>${s.mode==='recall'?'Recalled':'Correct'}</span></div><div><strong class="wrong">${review}</strong><span>To revisit${skipped?' · '+skipped+' skipped':''}</span></div><div><strong>${s.ids.length-s.results.length}</strong><span>Not visited</span></div></div>${review?'<button class="primary" data-action="retry">Revisit these places →</button>':'<button class="primary" data-action="new">Start another session →</button>'}<button class="secondary" data-action="explore">Back to exploring</button></div>`;
}
function selectRiver(id){if(state.scope!=="india"||state.mode!=='explore'||!river(id))return;state.selectedCity=null;state.cityStateContext=null;state.stateSelected=null;state.selected=id;state.catalog=false;state.detail=true;state.indiaSidebar=true;updateWorldLayout();renderSidebar();renderMap();$("sidebar-content").scrollTop=0;announce(river(id).name+' selected.');}
document.addEventListener('click',event=>{
 const searchResult=event.target.closest('[data-search-result]');if(searchResult){activateSearchResult(searchResult.dataset.searchResult);return;}const city=event.target.closest('[data-city-select]');if(city){selectCity(city.dataset.citySelect,true);return;}
 const continent=event.target.closest('[data-world-continent]');if(continent){chooseWorldContinent(continent.dataset.worldContinent,continent.dataset.learning||'explore');return;}
 const worldTopic=event.target.closest('[data-world-topic]');if(worldTopic){chooseWorldTopic(worldTopic.dataset.worldTopic,worldTopic.dataset.learning||'explore');return;}
 const feature=event.target.closest('[data-world-select]');if(feature){selectWorldFeature(feature.dataset.worldSelect,true);return;}
 const topic=event.target.closest('[data-topic]');if(topic){chooseTopic(topic.dataset.topic,topic.dataset.learning||'explore');return;}
 const country=event.target.closest('[data-country-select]');if(country){selectCountry(country.dataset.countrySelect,true);return;}
 const scope=event.target.closest('[data-scope]');if(scope){setScope(scope.dataset.scope);return;}
 const mode=event.target.closest('[data-mode]');if(mode){setMode(mode.dataset.mode);return;}
 const select=event.target.closest('[data-select]');if(select){selectRiver(select.dataset.select);return;}
 const option=event.target.closest('[data-answer]');if(option){answer(option.dataset.answer);return;}
 const edit=event.target.closest('[data-edit]');if(edit){openPlaceEditor(edit.dataset.edit);return;}
 const action=event.target.closest('[data-action]')?.dataset.action;
 if(action==='save-edit'){savePlaceEdit();return;}if(action==='reset-edit'){resetPlaceEdit();return;}if(action==='close-edit'){$('place-editor').close();return;}
 if(action==='clear-selection'){clearSelection();return;}
 if(action==='topics'){if(state.scope==='world')openWorldTopics();else openTopics();return;}
 if(action==='open-explorer'){state.indiaSidebar=true;state.indiaLayers=false;updateWorldLayout();}
 if(action==='back'){state.detail=false;renderSidebar();renderMap();}
 if(action==='focus')focusRiver();
 if(action==='practice-group'){state.group=river(state.selected).system||river(state.selected).group;$("system").value=state.group;setMode('practice');}
 if(action==='start')startSession();
 if(action==='toggle-session-timer')toggleSessionTimer();
 if(action==='reveal')reveal();
 if(action==='known'||action==='again'){if(state.session?.revealed&&state.session.mode==='recall'){recordResult(action==='known'&&!state.session.timedOut);nextQuestion();}}
 if(action==='skip')answer(null);
 if(action==='next')nextQuestion();
 if(action==='end'){stopTimer();state.session.done=true;renderSidebar();renderMap();}
 if(action==='retry'){const ids=state.session.results.filter(r=>!r.ok).map(r=>r.id);startSession(ids);}
 if(action==='new')setMode(state.mode);
 if(action==='explore')setMode('explore');
});
$("search").addEventListener('input',e=>{state.query=e.target.value;state.detail=false;renderSidebar();renderMap();});
document.addEventListener('input',e=>{if(e.target.id==='world-topic-search'){state.worldTopicQuery=e.target.value;renderWorldCatalogRows();}if(e.target.id==='world-place-search'){state.worldQuery=e.target.value;updateWorldPlaceResults();renderWorldMap();}if(e.target.id==='south-search'){state.southQuery=e.target.value;$('south-place-list').innerHTML=southRows();renderWorldMap();}if(e.target.id==='topic-search'){state.topicQuery=e.target.value;renderCatalogRows();}if(e.target.id==='physical-search'){state.query=e.target.value;$("physical-list").innerHTML=physicalRows();renderMap();}if(e.target.id==='world-search'){state.worldQuery=e.target.value;$("world-country-list").innerHTML=worldList(worldCountries());renderWorldMap();}});
document.addEventListener('change',e=>{if(e.target.id==='world-feature-group'){state.group=e.target.value;updateWorldPlaceResults();renderWorldMap();}if(e.target.id==='session-region')chooseSessionRegion(e.target.value);if(e.target.id==='south-group'){state.southGroup=e.target.value;$('south-place-list').innerHTML=southRows();renderWorldMap();}if(e.target.id==='physical-group'){state.group=e.target.value;$("physical-list").innerHTML=physicalRows();renderMap();}if(e.target.id==='state-borders')setBoundaryVisibility('states',e.target.checked);if(e.target.id==='country-borders')setBoundaryVisibility('countries',e.target.checked);if(e.target.id==='world-region'){state.worldRegion=e.target.value;updateWorldPlaceResults();renderWorldMap();}});
$("world-sidebar-toggle").addEventListener('click',toggleWorldSidebar);
$("world-layers-toggle").addEventListener('click',()=>{const key=state.scope==='world'?'worldLayers':'indiaLayers';state[key]=!state[key];updateWorldLayout();});
document.addEventListener('change',e=>{if(e.target.id==='layer-labels'){state.labels=e.target.checked;$("labels").checked=state.labels;renderMap();}});
$("system").addEventListener('change',e=>{state.group=e.target.value;state.detail=false;const rows=visibleRivers();if(!rows.some(r=>r.id===state.selected))state.selected=null;renderSidebar();renderMap();});
document.addEventListener('change',e=>{if(e.target.id==='timer-enabled'){state.setupTimed=e.target.checked;$('timer-duration').disabled=!e.target.checked;}if(e.target.id==='timer-duration')state.setupSeconds=Number(e.target.value);if(e.target.id==='session-features-all'){state.sessionFeatures=e.target.checked?sessionFeatureOptions().map(o=>o.group):[];renderSetup();$('session-features-all')?.focus?.({preventScroll:true});}if(e.target.dataset?.sessionFeature){const group=e.target.dataset.sessionFeature;state.sessionFeatures=e.target.checked?[...new Set([...state.sessionFeatures,group])]:state.sessionFeatures.filter(g=>g!==group);renderSetup();document.querySelector('[data-session-feature="'+group+'"]')?.focus?.({preventScroll:true});}if(e.target.id==='session-system'){state.group=e.target.value;$("system").value=state.group;const timer=$("timer-enabled").checked;renderSidebar();$("timer-enabled").checked=timer;renderMap();}});
$("labels").addEventListener('change',e=>{state.labels=e.target.checked;updateWorldLayout();renderMap();});
$("zoom-in").addEventListener('click',()=>zoom(.78));$("zoom-out").addEventListener('click',()=>zoom(1.28));$("focus-river").addEventListener('click',focusRiver);
$("theme").addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='light'?'dark':'light';updateThemeButton();saveLocal();});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="map-information"]'))$('about').showModal();});document.querySelector('.dialog-close').addEventListener('click',()=>$("about").close());
const atlas=$("atlas");
function svgPoint(event){const point=new DOMPoint(event.clientX,event.clientY);return point.matrixTransform(atlas.getScreenCTM().inverse());}
// Keep every contact so a pinch never turns into a one-finger pan or tap.
const mapPointers=new Map();
let mapPinch=null,mapHadPinch=false;
function contactDistance(points){return Math.hypot(points[1].clientX-points[0].clientX,points[1].clientY-points[0].clientY);}
function contactMidpoint(points){return {clientX:(points[0].clientX+points[1].clientX)/2,clientY:(points[0].clientY+points[1].clientY)/2};}
function beginMapPinch(){const points=[...mapPointers.values()].slice(0,2),mid=contactMidpoint(points),anchor=svgPoint(mid);mapPinch={view:{...state.view},distance:Math.max(1,contactDistance(points)),mid,anchor:[anchor.x,anchor.y],scale:markerScale()};mapHadPinch=true;}
function pinchedView(gesture,points,scope=state.scope){const mid=contactMidpoint(points),view=zoomedView(gesture.view,gesture.distance/Math.max(1,contactDistance(points)),gesture.anchor,scope),scale=gesture.scale*view.w/gesture.view.w;return {...view,x:view.x-(mid.clientX-gesture.mid.clientX)*scale,y:view.y-(mid.clientY-gesture.mid.clientY)*scale};}
function startMapDrag(event,moved=false){return {pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,view:{...state.view},scale:markerScale(),moved,id:event.target?.closest('[data-river]')?.dataset.river,state:event.target?.closest('[data-state]')?.dataset.state,country:event.target?.closest('[data-country]')?.dataset.country,feature:event.target?.closest('[data-world-feature]')?.dataset.worldFeature,city:event.target?.closest('[data-city]')?.dataset.city};}
function mapPointerDown(event){if(event.button!==0)return;event.preventDefault();cancelViewMotion();mapPointers.set(event.pointerId,{clientX:event.clientX,clientY:event.clientY,pointerId:event.pointerId});atlas.setPointerCapture?.(event.pointerId);if(mapPointers.size===1){mapHadPinch=false;state.drag=startMapDrag(event);}else beginMapPinch();}
function mapPointerMove(event){if(!mapPointers.has(event.pointerId))return;event.preventDefault();mapPointers.set(event.pointerId,{clientX:event.clientX,clientY:event.clientY,pointerId:event.pointerId});if(mapPointers.size>=2&&mapPinch){setView(pinchedView(mapPinch,[...mapPointers.values()].slice(0,2)),false);return;}const drag=state.drag;if(!drag||drag.pointerId!==event.pointerId)return;const dx=event.clientX-drag.startX,dy=event.clientY-drag.startY;drag.moved ||= Math.hypot(dx,dy)>=6;setView({...drag.view,x:drag.view.x-dx*drag.scale,y:drag.view.y-dy*drag.scale},false);}
function mapPointerEnd(event,cancelled=false){if(!mapPointers.has(event.pointerId))return;mapPointers.delete(event.pointerId);const drag=state.drag;if(mapPointers.size>=2){beginMapPinch();return;}mapPinch=null;if(mapPointers.size===1){state.drag=startMapDrag([...mapPointers.values()][0],true);return;}state.drag=null;layoutPlaceLabels();const tap=!cancelled&&!mapHadPinch&&drag&&!drag.moved&&Math.hypot(event.clientX-drag.startX,event.clientY-drag.startY)<6;mapHadPinch=false;if(!tap)return;if(drag.city)selectCity(drag.city);else if(drag.feature)selectWorldFeature(drag.feature);else if(state.scope==='world'&&drag.country)selectCountry(drag.country);else if(drag.id)selectRiver(drag.id);else if(drag.state)selectState(drag.state);else if(!state.session||state.session.done)clearSelection();}
atlas.addEventListener('pointerdown',mapPointerDown);
atlas.addEventListener('pointermove',mapPointerMove);
atlas.addEventListener('pointerup',event=>mapPointerEnd(event));
atlas.addEventListener('pointercancel',event=>mapPointerEnd(event,true));
atlas.addEventListener('lostpointercapture',event=>mapPointerEnd(event,true));
atlas.addEventListener('wheel',handleWheel,{passive:false});
atlas.addEventListener('keydown',e=>{const s=e.target.closest('[data-state]');if(s&&['Enter',' '].includes(e.key)){e.preventDefault();selectState(s.dataset.state);return;}const c=e.target.closest('[data-country]');if(c&&['Enter',' '].includes(e.key)){e.preventDefault();selectCountry(c.dataset.country);}});
atlas.addEventListener('keydown',e=>{const selected=e.target.closest('[data-river]');if(selected&&['Enter',' '].includes(e.key)){e.preventDefault();selectRiver(selected.dataset.river);return;}if(['+','=','-','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key)){e.preventDefault();if(['+','='].includes(e.key))zoom(.78);else if(e.key==='-')zoom(1.28);else if(e.key==='Home')resetMap();else{const v=state.view,d=v.w*.06;setView({...v,x:v.x+(e.key==='ArrowLeft'?-d:e.key==='ArrowRight'?d:0),y:v.y+(e.key==='ArrowUp'?-d:e.key==='ArrowDown'?d:0)});}}});
function topicCard(id,name,count){return `<div class="topic-card"><button class="topic-name" data-topic="${id}">${name}<small>${count}</small></button><div class="topic-actions"><button data-topic="${id}" aria-label="Browse ${name}">◎</button><button data-topic="${id}" data-learning="practice">Practice</button><button data-topic="${id}" data-learning="recall">Recall</button></div></div>`;}
function renderCatalog(){$("sidebar-content").innerHTML='<div class="topic-catalog"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="topic-search" type="search" placeholder="Search places, capitals, topics…" aria-label="Search India map" value="'+esc(state.topicQuery)+'"></label><div id="topic-rows"></div></div>';renderCatalogRows();}
function renderCatalogRows(){if(state.topicQuery.trim()){$('topic-rows').innerHTML=globalSearchMarkup('india',state.topicQuery);return;}const q=state.topicQuery.toLocaleLowerCase(),mountain='Mountains, Peaks and Passes',rivers='Rivers and Drainage Basins';const cards=[['mountains',mountain,state.places.length],['rivers',rivers,state.rivers.length]].filter(([,name])=>!q||name.toLowerCase().includes(q));$("topic-rows").innerHTML=topicCard('all','All India places',state.rivers.length+state.places.length)+`<details class="topic-section" open><summary>Indian Physical Geography <small>${cards.length}</small></summary>${cards.length?cards.map(c=>topicCard(...c)).join(''):'<p class="empty">No matching topics.</p>'}</details><p class="catalog-footnote">${state.states.length} states &amp; union territories on the base map.<br>Choose a topic to browse or start a learning session.</p>`;}
function chooseTopic(topic,mode='explore'){if(!['all','rivers','mountains'].includes(topic))return;stopTimer();state.topic=topic;state.catalog=false;state.group='all';state.query='';$("search").value='';state.selectedCity=null;state.cityStateContext=null;state.selected=null;state.stateSelected=null;state.indiaSidebar=true;state.indiaLayers=false;resetMap();setMode(mode);}
function openTopics(){stopTimer();state.selectedCity=null;state.cityStateContext=null;state.catalog=true;state.mode='explore';state.session=null;state.detail=false;state.indiaSidebar=true;state.indiaLayers=false;updateWorldLayout();renderSidebar();renderMap();}
function physicalRows(){if(state.query.trim())return globalSearchMarkup('india',state.query);return visibleItems().map(r=>`<button class="river-row${r.id===state.selected?' active':''}" data-select="${esc(r.id)}"><span class="feature-symbol ${r.group}" aria-hidden="true">${r.kind==='point'?(r.group==='peak'?'▲':r.group==='pass'?'◇':'△'):'≈'}</span><span><span class="river-name">${esc(r.name)}</span><span class="river-meta">${esc(r.region||GROUPS[r.group])}</span></span></button>`).join('')||'<p class="empty">No places match your filters.</p>';}
function renderPhysicalList(){$("sidebar-content").innerHTML=`<div class="physical-controls"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="physical-search" type="search" placeholder="Search a place or region…" aria-label="Search physical places" value="${esc(state.query)}"></label><label class="filter-label" for="physical-group">FEATURE GROUP</label><select id="physical-group">${groupOptions()}</select><p class="physical-count">${activeItems().length} mapped places · ranges use representative markers</p></div><div id="physical-list" class="river-list">${physicalRows()}</div>`;$("physical-group").value=state.group;}
function renderTributaries(r){const children=state.rivers.filter(t=>t.parent===r.id);return `${r.geometrySource?`<p class="coordinate-note">${esc(r.geometryCoverage||'Generalised river course')} · ${esc(r.geometrySource)}${r.osmIds?.length?` · <a href="https://www.openstreetmap.org/${esc(r.osmIds[0])}" target="_blank" rel="noopener">View source ↗</a>`:''}</p>`:''}${r.parent?`<p class="river-parent">Part of <button data-select="${esc(r.parent)}">${esc(river(r.parent)?.name||r.parent)} ↗</button></p>`:''}${children.length?`<section class="tributary-list"><p class="eyebrow">MAPPED TRIBUTARIES · ${children.length}</p>${children.map(t=>`<button data-select="${esc(t.id)}">${esc(t.name)} <span>↗</span></button>`).join('')}</section>`:''}`;}
function renderPlaceMarkers(current,quizzing,hidden,visible){
 const show=!state.catalog&&state.topic!=='rivers';const points=show?state.places.filter(p=>quizzing?p.id===current?.id:visible.has(p.id)):[];
 $("places").innerHTML=points.map(p=>{const [x,y]=xy(p.label),active=p.id===current?.id,interactive=state.mode==='explore';return `<g class="physical-feature ${p.group}${active?' active':''}" ${interactive?`data-river="${esc(p.id)}" tabindex="0" role="button" aria-label="Explore ${esc(p.name)}"`:'aria-hidden="true"'}><g class="place-marker" data-x="${x}" data-y="${y}" transform="translate(${x} ${y})"><circle class="point-hit" r="13"/>${p.group==='pass'?'<path class="point-shape" d="M0 -6 6 0 0 6 -6 0Z"/>':p.group==='range'?'<path class="point-shape" d="M-9 5 -3 -5 0 0 4 -6 10 5Z"/>':'<path class="point-shape" d="M0 -7 7 6 -7 6Z"/>'}${!hidden&&state.labels?`<text x="11" y="4" class="point-label" data-label-max="${labelZoomLimit(p,'india')}" ${quizzing?'data-quiz-label="true"':''}>${esc(p.name)}</text>`:''}</g></g>`;}).join('');
}
function selectState(id){if(state.session&&!state.session.done)return;const s=state.states.find(s=>s.id===id);if(!s)return;state.selectedCity=null;state.cityStateContext=null;state.selected=null;state.detail=false;state.stateSelected=id;renderSidebar();renderMap();announce(s.name+' selected.');}

const WORLD_GROUPS={trench:'Ocean trenches','volcanic-belt':'Volcanic belts',coast:'Coastal places',political:'Countries & territories',city:'Cities & ports',island:'Islands',lake:'Lakes',range:'Mountain ranges',peak:'Peaks & volcanoes',desert:'Deserts',biome:'Grasslands & forests',plateau:'Plateaus',resource:'Resources & agriculture',waterfall:'Waterfalls',dam:'Dams',sea:'Seas & oceans',tectonic:'Tectonic plates',current:'Ocean currents',river:'Rivers & estuaries'};
const WORLD_SYMBOLS={trench:'⌄','volcanic-belt':'◈',coast:'◆',political:'□',city:'●',island:'◆',lake:'●',range:'△',peak:'▲',desert:'◇',biome:'♧',plateau:'▰',resource:'✦',waterfall:'≋',dam:'⊞',sea:'≈',tectonic:'◇',current:'↟',river:'≈'};
let viewFrame=null,viewTarget=null,wheelFrame=null,wheelPending=0,wheelPointer=null;
function markerScale(){const m=$('atlas').getScreenCTM?.();return m?.a?1/m.a:state.view.w/1000;}
function reducedMotion(){return typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;}
function cancelViewMotion(wheel=true){if(viewFrame!==null&&typeof cancelAnimationFrame==='function')cancelAnimationFrame(viewFrame);viewFrame=null;viewTarget=null;if(wheel){if(wheelFrame!==null&&typeof cancelAnimationFrame==='function')cancelAnimationFrame(wheelFrame);wheelFrame=null;wheelPending=0;}}
function smoothView(target){cancelViewMotion();if(typeof requestAnimationFrame!=='function'||reducedMotion()){setView(target);return;}viewTarget=target;const start={...state.view},began=performance.now();const frame=now=>{const t=Math.min(1,(now-began)/220),e=1-Math.pow(1-t,3);setView(Object.fromEntries(Object.keys(target).map(k=>[k,start[k]+(target[k]-start[k])*e])),t===1);if(t<1)viewFrame=requestAnimationFrame(frame);else{viewFrame=null;viewTarget=null;}};viewFrame=requestAnimationFrame(frame);}
function clearSelection(){state.selectedCity=null;state.cityStateContext=null;state.stateSelected=null;state.selected=null;state.detail=false;state.worldSelected=null;state.worldFeatureSelected=null;if(state.mode==='explore')renderSidebar();renderMap();announce('Selection cleared.');}
function renderSelection(){if(state.session&&!state.session.done){$('selection-card').innerHTML='';return;}let record=null,key='',meta='',cities=[];const city=cityById(state.selectedCity);if(city){record=city;key=city.placeId||city.id;meta=cityDescription(city)+(city.note?'\n'+city.note:'');}else if(state.scope==='india'){record=state.states.find(s=>s.id===state.stateSelected);key=record?.id;if(record){meta='Capital: '+record.capital;cities=visibleCities().filter(c=>!c.isStateCapital);}else if(state.mode==='explore'&&!state.catalog){record=river(state.selected);key=record?.id;if(record)meta=record.kind==='point'?(record.region||GROUPS[record.group]):record.mouth;}}else{record=state.worldPlaces.find(p=>p.id===state.worldFeatureSelected);if(record){key=record.id;meta=record.note||WORLD_GROUPS[record.group];if(Number.isFinite(record.motionBearing)){const compass=['N','NE','E','SE','S','SW','W','NW'];meta+=' · Motion: '+compass[Math.round(record.motionBearing/45)%8]+' ('+record.motionBearing+'°)';}}else{record=state.worldLand.find(c=>c.id===state.worldSelected);if(record){key='country-'+record.id;meta='Capital: '+record.capital;cities=visibleCities().filter(c=>!c.isCapital);}}}const cityList=cities.length?'<div class="selection-cities"><small>Mapped cities</small>'+cities.map(c=>'<button data-city-select="'+c.id+'">'+esc(c.name)+'</button>').join('')+'</div>':'';$('selection-card').innerHTML=record?'<button class="selection-close" data-action="clear-selection" aria-label="Clear map selection">×</button><strong>'+esc(record.name)+'</strong><span>'+esc(meta)+'</span>'+cityList+'<button class="selection-edit" data-edit="'+esc(key)+'" aria-label="Edit '+esc(record.name)+'">✎</button>':'';}
function renderSymbolLegend(){const layers=state.scope==='world'?state.worldLayers:state.indiaLayers;$('symbol-legend').hidden=!layers;let rows=state.scope==='india'?(state.catalog?[['boundary','□','State / UT boundary']]:state.topic==='rivers'?[['river','━','River'],['selected','━','Selected river']]:[['range','△','Mountain range'],['peak','▲','Peak'],['pass','◇','Pass'],...(state.topic==='all'?[['river','━','River']]:[])]):state.worldCatalog?[['boundary','□','Country boundary']]:[...new Set(worldVisible().map(p=>p.group))].map(g=>[g,g==='country'?'□':WORLD_SYMBOLS[g],g==='country'?'Country / territory':WORLD_GROUPS[g]]);if(rows.some(([group])=>group==='tectonic'))rows.push(['tectonic','➝','Plate motion (NNR-MORVEL56)']);if(visibleCities().length)rows.push(['capital','●','Capital city'],['city','●','Other city']);rows=rows.flatMap(([g,s,n])=>g==='current'?[['warm','→','Warm current'],['cold','→','Cold current']]:[[g,s,n]]);const boundaryControls='<div class="key-controls">'+(state.scope==='india'?'<label><input id="state-borders" type="checkbox" '+(state.stateBorders?'checked':'')+'> State / UT boundaries</label>':'')+'<label><input id="country-borders" type="checkbox" '+((state.scope==='world'?state.worldBorders:state.indiaCountryBorders)?'checked':'')+'> Country boundaries</label><label><input id="important-latitudes" type="checkbox" '+(state.latitudes?'checked':'')+'> Important latitudes</label></div>';$('symbol-legend').innerHTML='<small>MAP KEY</small>'+boundaryControls+rows.map(([c,s,n])=>'<span><i class="key-symbol '+c+'">'+s+'</i>'+n+'</span>').join('')+'<button class="key-info" data-action="map-information">Data &amp; storage</button>';}
function southPlaces(){const q=state.southQuery.trim().toLocaleLowerCase();return state.worldPlaces.filter(p=>(state.southGroup==='all'||p.group===state.southGroup)&&(!q||[p.name,p.note,WORLD_GROUPS[p.group]].join(' ').toLocaleLowerCase().includes(q)));}
function southRows(){const rows=southPlaces();return rows.length?rows.map(p=>'<button class="world-country-row'+(p.id===state.worldFeatureSelected?' active':'')+'" data-world-select="'+esc(p.id)+'"><span class="key-symbol '+p.group+'">'+WORLD_SYMBOLS[p.group]+'</span> '+esc(p.name)+'<small>'+esc(WORLD_GROUPS[p.group])+' · PDF p. '+p.pdfPage+'</small></button>').join(''):'<p class="empty">No locations match your search.</p>';}
function chooseWorldTopic(topic,mode='explore'){if(!WORLD_TOPICS[topic]&&topic!=='all')return;stopTimer();state.selectedCity=null;state.cityStateContext=null;state.worldTopic=topic;state.worldContinent=false;state.worldCatalog=false;state.worldSelected=null;state.worldFeatureSelected=null;state.worldQuery='';state.worldRegion='all';state.group='all';state.sessionRegionChosen=false;state.sessionFeatures=[];state.worldSidebar=true;state.worldLayers=false;setMode(mode);if(topic!=='countries'&&topic!=='all')fitWorldTopic();else resetMap();$('sidebar-content').scrollTop=0;}
function openWorldTopics(){stopTimer();state.session=null;state.mode='explore';state.selectedCity=null;state.cityStateContext=null;state.worldCatalog=true;state.worldSidebar=true;state.worldLayers=false;state.worldSelected=null;state.worldFeatureSelected=null;updateWorldLayout();renderSidebar();resetMap();renderMap();$('sidebar-content').scrollTop=0;}
function selectWorldFeature(id,focus=false){if(state.session&&!state.session.done)return;const p=state.worldPlaces.find(p=>p.id===id);if(!p)return;if(p.cityId){selectCity(p.cityId,focus);return;}state.selectedCity=null;state.cityStateContext=null;state.worldFeatureSelected=id;state.worldSelected=null;document.querySelectorAll('.world-country.active').forEach(el=>el.classList.remove('active'));renderSelection();renderSymbolLegend();renderWorldFeatures();if($('world-place-list'))updateWorldPlaceResults();if(focus)focusWorldStudy(p);announce(p.name+' selected.');}
function plateMotionArrow(place) {
 if (!Number.isFinite(place.motionBearing)) return '';
 return '<path class="plate-motion-arrow" aria-hidden="true" d="M0 14V-15M-5-9L0-15L5-9" transform="rotate('+place.motionBearing+')"/>';
}
function renderWorldFeatures(){const s=state.session,quizzing=!!s&&!s.done,target=quizzing?river(s.ids[s.index]):null,hidden=quizzing&&!s.revealed,points=quizzing?(target.kind==='country'?[]:[target]):state.worldCatalog?[]:worldVisible().filter(p=>p.kind!=='country');const guides='';const displayedCityIds=new Set(visibleCities().map(c=>c.id));const sorted=points.filter(p=>!p.cityId||!displayedCityIds.has(p.cityId)).sort((a,b)=>Number(!!b.geometry)-Number(!!a.geometry)||Number(a.id===state.worldFeatureSelected)-Number(b.id===state.worldFeatureSelected));$('world-features').innerHTML=guides+sorted.map(p=>{const [x,y]=worldXY(p.label),active=quizzing||p.id===state.worldFeatureSelected,current=p.group==='current',area=p.geometry?'<path class="feature-area '+(p.group==='tectonic'?'plate-area':'region-area')+'" fill-rule="evenodd" d="'+worldPath(p.geometry)+'"/>':'',d=current?p.lines?.map(currentPath).join(''):p.lines?.map(l=>l.map((point,i)=>(i?'L':'M')+worldXY(point).join(',')).join('')).join(''),routes=d?(current?'<path class="current-glow" d="'+d+'"/><path class="current-line" marker-end="url(#current-'+p.temperature+')" d="'+d+'"/><path class="route-hit" d="'+d+'"/>':'<path class="south-river" d="'+d+'"/><path class="route-hit" d="'+d+'"/>'):'',point=p.group==='tectonic'&&!quizzing?plateMotionArrow(p):p.group==='city'?'<circle class="city-dot'+(isCapitalCity(cityById(p.cityId)||{})?' capital-dot':'')+'" r="3.1"/>':current||p.group==='river'&&p.lines?.length?'<circle class="route-anchor" r="2.5"/>':'<text class="world-glyph" text-anchor="middle" y="4">'+WORLD_SYMBOLS[p.group]+'</text>';return '<g class="world-feature '+p.group+(p.temperature?' '+p.temperature:'')+(active?' active':'')+'" '+(quizzing?'aria-hidden="true"':'data-world-feature="'+p.id+'" tabindex="0" role="button" aria-label="Explore '+esc(p.name)+'"')+'>'+area+routes+'<g class="place-marker" data-x="'+x+'" data-y="'+y+'"><circle class="point-hit" r="12"/>'+point+(!hidden&&state.labels?'<text class="point-label" data-label-max="'+labelZoomLimit(p,'world')+'" '+(quizzing?'data-quiz-label="true"':'')+' x="11" y="4">'+esc(p.name)+'</text>':'')+'</g></g>';}).join('');renderCityMarkers();setView(state.view);}
function layoutPlaceLabels(){const nodes=[...document.querySelectorAll('.place-marker')],scale=markerScale(),boxes=[],m=$('atlas').getScreenCTM?.(),bounds=$('atlas').getBoundingClientRect?.();for(const selector of ['.symbol-legend','.map-tools','.selection-card']){const element=document.querySelector(selector),r=element?.getBoundingClientRect?.();if(r&&r.width&&r.height)boxes.push({x:r.left-5,y:r.top-5,w:r.width+10,h:r.height+10});}nodes.sort((a,b)=>Number(b.parentElement?.classList.contains('active'))-Number(a.parentElement?.classList.contains('active')));for(const el of nodes){const text=el.querySelector('.point-label');if(!text||text.style.display==='none')continue;const x=Number(el.dataset.x)/scale+(m?.e||0),y=Number(el.dataset.y)/scale+(m?.f||0),w=text.getComputedTextLength?text.getComputedTextLength():text.textContent.length*6;let dx=11,dy=4,box;for(let i=0;i<120;i++){dx=i%2?-(w+11):11;dy=4+Math.ceil(i/2)*14*(i%4<2?1:-1);if(bounds)dx=Math.max(bounds.left+7-x,Math.min(bounds.right-7-x-w,dx));box={x:x+dx,y:y+dy-10,w:w+4,h:14};if(!boxes.some(b=>box.x<b.x+b.w&&box.x+box.w>b.x&&box.y<b.y+b.h&&box.y+box.h>b.y))break;}boxes.push(box);text.setAttribute('x',dx);text.setAttribute('y',dy);let leader=el.querySelector('.label-leader');if(Math.abs(dy)>8||Math.abs(dx)!==11){if(!leader){leader=document.createElementNS('http://www.w3.org/2000/svg','path');leader.setAttribute('class','label-leader');el.insertBefore(leader,text);}leader.setAttribute('d','M0 0L'+(dx>0?dx-3:dx+w+3)+' '+(dy-4));}else if(leader)leader.remove();}}
atlas.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!state.session||state.session.done)clearSelection();return;}const p=e.target.closest('[data-world-feature]');if(p&&['Enter',' '].includes(e.key)){e.preventDefault();selectWorldFeature(p.dataset.worldFeature);}});


const WORLD_TOPICS={
 countries:{name:'Countries and Regions',groups:['country','political']},
 mountains:{name:'Mountains, Plateaus and Deserts',groups:['range','peak','plateau','desert']},
 waters:{name:'World Rivers and Lakes',groups:['river','lake','waterfall','dam']},
 seas:{name:'Seas, Straits and Canals',groups:['sea']},
 oceans:{name:'Ocean Relief and Currents',groups:['current']},
 plates:{name:'Tectonic Plates',groups:['tectonic']},
 subduction:{name:'Ring of Fire and Trenches',groups:['volcanic-belt','trench']},
 biomes:{name:'World Climate and Biomes',groups:['biome']},
 places:{name:'Cities, Islands and Resources',groups:['city','island','resource','coast']}
};
function worldItems(){return [...state.worldLand.map(c=>({id:'country-'+c.id,countryId:c.id,name:c.name,kind:'country',group:'country',region:c.continent,label:c.label,note:'Capital: '+c.capital+(c.note?' · '+c.note:''),capital:c.capital})),...state.worldPlaces.filter(p=>!p.countryId).map(p=>({...p,kind:'point',region:p.region||'South America'}))];}
function continentItems(name){const items=worldItems().filter(p=>p.region===name);return items.filter(p=>p.kind!=='country'||!items.some(q=>q.kind!=='country'&&q.name===p.name));}
function worldPool(){const groups=WORLD_TOPICS[state.worldTopic]?.groups;return (state.worldContinent?continentItems(state.worldRegion):worldItems()).filter(p=>(state.worldTopic==='all'||groups?.includes(p.group))&&(state.worldRegion==='all'||p.region===state.worldRegion));}
function worldVisible(){const q=state.worldQuery.trim().toLocaleLowerCase();return worldPool().filter(matchesGroup).filter(p=>!q||[p.name,p.note,p.region,WORLD_GROUPS[p.group],p.capital].join(' ').toLocaleLowerCase().includes(q));}
function worldGroupOptions(){const groups=[...new Set(worldPool().map(p=>p.group))];return '<option value="all">All feature types</option>'+groups.map(g=>'<option value="'+g+'"'+(g===state.group?' selected':'')+'>'+esc(g==='country'?'Countries':WORLD_GROUPS[g])+'</option>').join('');}
function worldRegionControl(id){if(state.worldContinent)return '';return '<label class="filter-label" for="'+id+'">REGION</label><select id="'+id+'"><option value="all">All regions</option>'+['South America','Africa','Asia','Europe','North America','Oceania','Antarctica','Oceans and Seas','Seven seas (open ocean)'].map(n=>'<option'+(state.worldRegion===n?' selected':'')+'>'+esc(n)+'</option>').join('')+'</select>';}
function worldPlaceRows(){if(state.worldQuery.trim())return globalSearchMarkup('world',state.worldQuery);const rows=worldVisible();return rows.length?rows.map(p=>'<div class="editable-place-row"><button class="world-country-row" '+(p.kind==='country'?'data-country-select="'+p.countryId+'"':'data-world-select="'+p.id+'"')+'><span class="key-symbol '+p.group+'">'+(p.kind==='country'?'□':WORLD_SYMBOLS[p.group])+'</span> '+esc(p.name)+'<small>'+esc(p.kind==='country'?p.region:WORLD_GROUPS[p.group]+' · '+(p.temperature?p.temperature+' · '+p.ocean:p.region))+'</small></button><button class="edit-row-button" data-edit="'+p.id+'" aria-label="Edit '+esc(p.name)+'">✎</button></div>').join(''):'<p class="empty">No places match your filters.</p>';}
function worldTopicCard(id,name,count){return '<div class="topic-card"><button class="topic-name" data-world-topic="'+id+'">'+esc(name)+'<small>'+count+'</small></button><div class="topic-actions"><button data-world-topic="'+id+'" aria-label="Browse '+esc(name)+'">◎</button><button data-world-topic="'+id+'" data-learning="practice">Practice</button><button data-world-topic="'+id+'" data-learning="recall">Recall</button></div></div>';}
function renderWorldCatalog(){$('sidebar-content').innerHTML='<div class="topic-catalog"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="world-topic-search" type="search" placeholder="Search places, capitals, topics…" aria-label="Search World map" value="'+esc(state.worldTopicQuery)+'"></label><div id="world-topic-rows"></div></div>';renderWorldCatalogRows();}
function renderWorldCatalogRows(){if(state.worldTopicQuery.trim()){$('world-topic-rows').innerHTML=globalSearchMarkup('world',state.worldTopicQuery);return;}const q=state.worldTopicQuery.trim().toLocaleLowerCase(),items=worldItems(),rows=Object.entries(WORLD_TOPICS).filter(([,t])=>!q||t.name.toLocaleLowerCase().includes(q)),south=continentItems('South America'),continent=!q||'south america by continent'.includes(q);$('world-topic-rows').innerHTML=worldTopicCard('all','All World places',items.length)+(rows.length?'<details class="topic-section" open><summary>World Geography <small>'+rows.length+'</small></summary>'+rows.map(([id,t])=>worldTopicCard(id,t.name,items.filter(p=>t.groups.includes(p.group)).length)).join('')+'</details>':'')+(continent?'<details class="topic-section continent-section" open><summary>By Continent <small>1</small></summary>'+worldContinentCard('South America',south.length)+'</details>':'')+(!rows.length&&!continent?'<p class="empty">No matching topics.</p>':'');}
function worldContinentCard(name,count){return '<div class="topic-card"><button class="topic-name" data-world-continent="'+esc(name)+'">'+esc(name)+'<small>'+count+'</small></button><div class="topic-actions"><button data-world-continent="'+esc(name)+'" aria-label="Browse '+esc(name)+'">◎</button><button data-world-continent="'+esc(name)+'" data-learning="practice">Practice</button><button data-world-continent="'+esc(name)+'" data-learning="recall">Recall</button></div></div>';}
function chooseWorldContinent(name,mode='explore'){if(name!=='South America')return;chooseWorldTopic('all',mode);state.worldContinent=true;state.worldRegion=name;state.sessionRegionChosen=true;state.sessionFeatures=sessionFeatureOptions().map(o=>o.group);renderSidebar();fitSouthAmerica();renderMap();}
function fitWorldTopic(){if(['oceans','plates','subduction'].includes(state.worldTopic))resetMap();else fitSouthAmerica();}
function fitSouthAmerica(){fitProjectedPoints([worldXY([-95,14]),worldXY([-30,-58])],85);}
function fitProjectedPoints(points,min=90){
 const finite=points.filter(p=>p.every(Number.isFinite));if(!finite.length)return;const xs=finite.map(p=>p[0]),ys=finite.map(p=>p[1]),width=atlas.clientWidth||900,height=atlas.clientHeight||750,top=activeSession()?100:0,bottom=activeSession()?Math.min(height*.5,($('session-overlay').getBoundingClientRect?.().height||210)+35):0,available=Math.max(80,height-top-bottom),aspect=width/available,cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2,w=Math.min(1100,Math.max(min,(Math.max(...xs)-Math.min(...xs))*1.25,(Math.max(...ys)-Math.min(...ys))*1.25*aspect)),h=w*height/width;setView({x:cx-w/2,y:cy-(top+available/2)*w/width,w,h});
}
function geometryPoints(geometry){return geometry.coordinates.flat(geometry.type==='Polygon'?1:2);}
function focusWorldStudy(p){cancelViewMotion();if(p.kind==='country'){const c=state.worldLand.find(c=>c.id===p.countryId);if(c){fitProjectedPoints(geometryPoints(c.geometry).filter(c=>Math.abs(c[0]-p.label[0])<60&&Math.abs(c[1]-p.label[1])<65).map(worldXY),activeSession()?40:120);return;}}if(p.geometry){fitProjectedPoints(geometryPoints(p.geometry).map(worldXY),95);return;}if(p.lines?.length){
 const lines=p.id==='aleutian-trench'?p.lines.filter(line=>line.some(([lon])=>Math.abs(lon-p.label[0])<35)):p.lines;
 fitProjectedPoints(lines.flat().map(worldXY),110);return;
 }const [x,y]=worldXY(p.label),w=p.group==='biome'?210:130;if(activeSession())fitProjectedPoints([[x,y]],w);else setView({x:x-w/2,y:y-w/2,w,h:w});}
function wheelDeltaPixels(event){return Math.max(-160,Math.min(160,event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?800:1)*(event.ctrlKey?3:1)));}
function handleWheel(event){event.preventDefault();if(state.drag)return;cancelViewMotion(false);const delta=wheelDeltaPixels(event);if(!delta)return;if(Math.sign(delta)!==Math.sign(wheelPending))wheelPending=0;wheelPending=Math.max(-360,Math.min(360,wheelPending+delta));wheelPointer={clientX:event.clientX,clientY:event.clientY};if(typeof requestAnimationFrame!=='function'||reducedMotion()){const p=svgPoint(wheelPointer);setView(zoomedView(state.view,Math.exp(wheelPending*.00125),[p.x,p.y]));wheelPending=0;return;}if(wheelFrame===null)wheelFrame=requestAnimationFrame(stepWheel);}
function stepWheel(){const step=Math.max(-40,Math.min(40,wheelPending*.28)),p=svgPoint(wheelPointer);wheelPending-=step;setView(zoomedView(state.view,Math.exp(step*.00125),[p.x,p.y]),false);if(Math.abs(wheelPending)>.06)wheelFrame=requestAnimationFrame(stepWheel);else{wheelPending=0;wheelFrame=null;layoutPlaceLabels();}}
function editableRecord(id){if(id?.startsWith('country-'))return state.worldLand.find(c=>c.id===id.slice(8));return [...state.rivers,...state.places,...state.worldPlaces,...state.states,...state.cities].find(p=>p.id===id);}
function editableFields(record,id){return id.startsWith('country-')||id.startsWith('IN-')?['name','capital','note']:['name',...['source','mouth','route','region'].filter(k=>Object.hasOwn(record,k)),'note'];}
function captureOriginals(){invalidateMapSearch();for(const r of [...state.rivers,...state.places,...state.worldPlaces,...state.states,...state.worldLand,...state.cities]){const key=state.worldLand.includes(r)?'country-'+r.id:r.id;state.originals[key]=Object.fromEntries(editableFields(r,key).map(k=>[k,r[k]||'']));}}
function applyStoredEdits(){invalidateMapSearch();for(const [id,fields] of Object.entries(state.edits)){const record=editableRecord(id);if(!record||!fields||typeof fields!=='object')continue;for(const key of editableFields(record,id)){if(typeof fields[key]==='string'&&(key!=='name'||fields[key].trim()))record[key]=fields[key].slice(0,key==='note'?8000:2000);}}}
function openPlaceEditor(id){if(state.session&&!state.session.done)return;const r=editableRecord(id);if(!r)return;state.editTarget=id;const fields=editableFields(r,id);if(!state.originals[id])state.originals[id]=Object.fromEntries(fields.map(k=>[k,r[k]||'']));$('editor-title').textContent='Edit '+r.name;$('editor-fields').innerHTML=fields.map(k=>'<div class="editor-field"><label for="edit-'+k+'">'+esc({name:'Name',capital:'Capital / administrative centres',note:'Information / notes',source:'Source / location',mouth:'Destination / feature type',route:'Course / description',region:'Region'}[k]||k)+'</label>'+(k==='note'?'<textarea id="edit-'+k+'" rows="6" maxlength="8000">'+esc(r[k]||'')+'</textarea>':'<input id="edit-'+k+'" value="'+esc(r[k]||'')+'" maxlength="2000">')+'</div>').join('');$('edit-error').textContent='';$('place-editor').showModal();}
function commitPlaceEdit(id,values){const r=editableRecord(id);if(!r||!values.name?.trim())return false;const edit={...state.edits[id]};for(const field of editableFields(r,id)){if(typeof values[field]==='string'){const value=values[field].trim().slice(0,field==='note'?8000:2000);if(value!==r[field])edit[field]=value;}}state.edits[id]=edit;Object.assign(r,edit);invalidateMapSearch();saveLocal();return true;}
function savePlaceEdit(){const id=state.editTarget,r=editableRecord(id);if(!r)return;const values=Object.fromEntries(editableFields(r,id).map(k=>[k,$('edit-'+k).value]));if(!commitPlaceEdit(id,values)){$('edit-error').textContent='Enter a place name.';return;}$('place-editor').close();renderSidebar();renderMap();announce(state.storageOK?'Information saved in this browser.':'Information updated for this visit; browser saving is unavailable.');}
function resetPlaceEdit(){const id=state.editTarget,r=editableRecord(id);if(!r||!state.originals[id])return;Object.assign(r,state.originals[id]);delete state.edits[id];invalidateMapSearch();saveLocal();$('place-editor').close();renderSidebar();renderMap();announce('Original information restored.');}


function labelZoomLimit(p,scope=state.scope){if(scope==='india')return p.group==='range'?1300:1150;return p.geometry||['current','river','sea','biome'].includes(p.group)?1200:800;}
function labelVisibleAt(p,width,scope=state.scope,revealed=false){return revealed||width<=labelZoomLimit(p,scope);}
function updateMapLabelVisibility(){const v=state.view,pad=markerScale()*10;document.querySelectorAll('.point-label,.river-label').forEach(el=>{const parent=el.parentElement,x=Number(parent?.dataset.x??el.getAttribute('x')),y=Number(parent?.dataset.y??el.getAttribute('y')),inside=!Number.isFinite(x)||!Number.isFinite(y)||(x>=v.x-pad&&x<=v.x+v.w+pad&&y>=v.y-pad&&y<=v.y+v.h+pad),visible=el.dataset.quizLabel==='true'||inside&&(parent?.closest?.('.active')||el.classList.contains('active')||v.w<=Number(el.dataset.labelMax||800));el.style.display=visible?'':'none';});}
function currentPath(line){const points=line.map(worldXY);if(!points.length)return '';let d='M'+points[0].join(',');for(let i=1;i<points.length;i++){const p0=points[i-2]||points[i-1],p1=points[i-1],p2=points[i],p3=points[i+1]||p2,c1=[p1[0]+(p2[0]-p0[0])/7,p1[1]+(p2[1]-p0[1])/7],c2=[p2[0]-(p3[0]-p1[0])/7,p2[1]-(p3[1]-p1[1])/7];d+='C'+c1.join(',')+' '+c2.join(',')+' '+p2.join(',');}return d;}



function updateWorldPlaceResults(){const list=$('world-place-list');if(!list)return;list.innerHTML=worldPlaceRows();const count=$('world-list-count');if(count)count.textContent=(state.worldQuery.trim()?globalSearch('world',state.worldQuery).length+' RESULTS':worldVisible().length+' PLACES');}
function isCapitalCity(city){return !!(city.isCapital||(state.scope==='india'&&city.isStateCapital));}
function cityById(id){const c=state.cities.find(c=>c.id===id);if(!c)return null;const place=state.worldPlaces.find(p=>p.id===c.placeId);return {...c,name:place?.name||c.name,note:place?.note||c.note};}
function cityDescription(c){const country=state.worldLand.find(p=>p.id===c.countryId)?.name||c.countryId,states=(c.stateIds||[]).map(id=>state.states.find(s=>s.id===id)?.name).filter(Boolean);return (state.scope==='india'&&c.isStateCapital?'State / UT capital':c.capitalRole||'City')+' · '+(state.scope==='india'&&states.length?states.join(', '):country);}
function visibleCities(){if(state.session&&!state.session.done)return [];const selected=cityById(state.selectedCity);if(state.scope==='world'){const country=state.worldSelected||selected?.countryId;return country?state.cities.filter(c=>c.countryId===country).map(c=>cityById(c.id)):[];}const stateId=state.stateSelected||state.cityStateContext||selected?.stateIds?.[0];if(stateId)return state.cities.filter(c=>c.countryId==='IND'&&c.stateIds?.includes(stateId)).map(c=>cityById(c.id));return selected?[selected]:[];}
function renderCityMarkers(){const cities=visibleCities();$('city-overlays').innerHTML=cities.map(c=>{const [x,y]=(state.scope==='world'?worldXY:xy)(c.label);return '<g class="city-feature'+(c.id===state.selectedCity?' active':'')+'" data-city="'+c.id+'" tabindex="0" role="button" aria-label="Explore city '+esc(c.name)+'"><g class="place-marker" data-x="'+x+'" data-y="'+y+'"><circle class="point-hit" r="11"/><circle class="city-dot'+(isCapitalCity(c)?' capital-dot':'')+'" r="3.1"/>'+(state.labels?'<text class="point-label" x="9" y="4" data-label-max="'+(state.scope==='world'?900:1150)+'">'+esc(c.name)+'</text>':'')+'</g></g>';}).join('');}
function selectCity(id,focus=false){if(state.session&&!state.session.done)return;const c=cityById(id);if(!c||state.scope==='india'&&c.countryId!=='IND')return;const stateContext=state.stateSelected||state.cityStateContext||c.stateIds?.[0]||null;state.selectedCity=id;state.cityStateContext=state.scope==='india'?stateContext:null;state.selected=null;state.stateSelected=null;state.detail=false;state.worldSelected=null;state.worldFeatureSelected=null;renderSidebar();renderMap();if(focus){const [x,y]=(state.scope==='world'?worldXY:xy)(c.label),w=state.scope==='world'?125:280,h=state.scope==='world'?125:252;smoothView({x:x-w/2,y:y-h/2,w,h});}announce(c.name+' selected.');}
function normalSearch(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();}
const MAP_SEARCH_CACHE=new Map();
function invalidateMapSearch(){MAP_SEARCH_CACHE.clear();}
function searchRecords(scope){if(MAP_SEARCH_CACHE.has(scope))return MAP_SEARCH_CACHE.get(scope);const result=[];if(scope==='world'){for(const c of state.worldLand){const cities=state.cities.filter(p=>p.countryId===c.id).map(p=>cityById(p.id).name);result.push({key:'country:'+c.id,name:c.name,meta:'Country / territory · Capital: '+c.capital,text:[c.name,c.capital,c.continent,c.note,...cities].join(' ')});}for(const p of state.worldPlaces.filter(p=>!p.cityId&&!p.countryId))result.push({key:'feature:'+p.id,name:p.name,meta:(WORLD_GROUPS[p.group]||'Place')+' · '+(p.region||'South America'),text:[p.name,p.note,p.region,p.ocean,WORLD_GROUPS[p.group]].join(' ')});for(const [id,t]of Object.entries(WORLD_TOPICS))result.push({key:'topic:'+id,name:t.name,meta:'World topic',text:t.name});result.push({key:'continent:South America',name:'South America',meta:'Continent collection',text:'South America continent'});}else{for(const s of state.states)result.push({key:'state:'+s.id,name:s.name,meta:'State / UT · Capital: '+s.capital,text:[s.name,s.capital,s.note].join(' ')});for(const p of [...state.rivers,...state.places])result.push({key:'feature:'+p.id,name:p.name,meta:GROUPS[p.group]||'Place',text:[p.name,p.source,p.mouth,p.route,p.region,p.note,GROUPS[p.group]].join(' ')});result.push({key:'topic:rivers',name:'Rivers and Drainage Basins',meta:'India topic',text:'Rivers and Drainage Basins'},{key:'topic:mountains',name:'Mountains, Peaks and Passes',meta:'India topic',text:'Mountains Peaks Passes'});}for(const raw of state.cities.filter(c=>scope==='world'||c.countryId==='IND')){const c=cityById(raw.id),country=state.worldLand.find(p=>p.id===c.countryId)?.name||c.countryId,states=(c.stateIds||[]).map(id=>state.states.find(s=>s.id===id)?.name).filter(Boolean),meta=(scope==='india'&&c.isStateCapital?'State / UT capital':c.capitalRole||'City')+' · '+(scope==='india'&&states.length?states.join(', '):country);result.push({key:'city:'+c.id,name:c.name,meta,text:[c.name,meta,c.note,country,...states,...c.aliases,'city cities capital capitals'].join(' ')});}const indexed=result.map(r=>({...r,normal:normalSearch(r.name+" "+r.meta+" "+r.text),normalName:normalSearch(r.name)}));MAP_SEARCH_CACHE.set(scope,indexed);return indexed;}
function globalSearch(scope,query){const q=normalSearch(query),tokens=q.split(' ').filter(Boolean);if(!tokens.length)return [];return searchRecords(scope).filter(r=>tokens.every(t=>r.normal.includes(t))).map(r=>({...r,score:r.normalName===q?0:r.normalName.startsWith(q)?1:r.normalName.includes(q)?2:3})).sort((a,b)=>a.score-b.score||a.name.localeCompare(b.name));}
function globalSearchMarkup(scope,query){const rows=globalSearch(scope,query);return '<div class="map-search-results"><p class="search-result-count">'+rows.length+' results across '+(scope==='india'?'India':'World')+'</p>'+rows.map(r=>'<button class="search-result" data-search-result="'+esc(r.key)+'"><strong>'+esc(r.name)+'</strong><small>'+esc(r.meta)+'</small></button>').join('')+(rows.length?'':'<p class="empty">No matching mapped places or topics.</p>')+'</div>';}
function activateSearchResult(key){const index=key.indexOf(':'),kind=key.slice(0,index),id=key.slice(index+1);if(kind==='city'){selectCity(id,true);return;}if(kind==='country'){selectCountry(id,true);return;}if(kind==='state'){selectState(id);const s=state.states.find(s=>s.id===id);if(s){const points=geometryPoints(s.geometry).map(xy),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),w=Math.max(220,Math.max(...xs)-Math.min(...xs)+120,(Math.max(...ys)-Math.min(...ys)+120)/.9),h=w*.9;smoothView({x:(Math.min(...xs)+Math.max(...xs)-w)/2,y:(Math.min(...ys)+Math.max(...ys)-h)/2,w,h});}return;}if(kind==='topic'){if(state.scope==='world')chooseWorldTopic(id);else chooseTopic(id);return;}if(kind==='continent'){chooseWorldContinent(id);return;}if(kind==='feature'){if(state.scope==='world'){const p=state.worldPlaces.find(p=>p.id===id);if(!p)return;const topic=Object.entries(WORLD_TOPICS).find(([,t])=>t.groups.includes(p.group))?.[0]||'all';chooseWorldTopic(topic);selectWorldFeature(id,true);}else{const p=[...state.rivers,...state.places].find(p=>p.id===id);if(!p)return;chooseTopic(p.kind==='point'?'mountains':'rivers');selectRiver(id);focusRiver();}}}
atlas.addEventListener('keydown',event=>{const city=event.target.closest('[data-city]');if(city&&['Enter',' '].includes(event.key)){event.preventDefault();selectCity(city.dataset.city);}});

document.addEventListener('keydown',event=>{if(event.key!=='Enter'||!['topic-search','world-topic-search','search','physical-search','world-place-search'].includes(event.target.id))return;const result=globalSearch(state.scope,event.target.value)[0];if(result){event.preventDefault();activateSearchResult(result.key);}});
function loadMapSettings(settings){if(!settings||typeof settings!=='object')return;for(const key of ['latitudes','stateBorders','indiaCountryBorders','worldBorders'])if(typeof settings[key]==='boolean')state[key]=settings[key];if(Number.isFinite(settings.sidebarWidth))state.sidebarWidth=Math.max(240,Math.min(640,settings.sidebarWidth));}
function syncBoundaryVisibility(){document.documentElement.dataset.stateBorders=String(state.stateBorders);document.documentElement.dataset.countryBorders=String(state.scope==='world'?state.worldBorders:state.indiaCountryBorders);}
function setBoundaryVisibility(kind,visible){if(kind==='states')state.stateBorders=!!visible;else state[state.scope==='world'?'worldBorders':'indiaCountryBorders']=!!visible;syncBoundaryVisibility();renderMap();saveLocal();}
function sidebarLimits(viewport){const max=Math.max(160,Math.min(640,viewport-(viewport<=640?48:120)));return {min:Math.min(240,max),max};}
function viewportWidth(){return typeof window==='undefined'?1200:window.innerWidth;}
function applySidebarWidth(){const viewport=viewportWidth(),limits=sidebarLimits(viewport),preferred=state.sidebarWidth??(viewport>850?420:viewport>640?340:310),width=Math.round(Math.max(limits.min,Math.min(limits.max,preferred)));state.appliedSidebarWidth=width;document.documentElement.style?.setProperty('--sidebar-width',width+'px');const handle=$('sidebar-resize');handle.setAttribute('aria-valuemin',limits.min);handle.setAttribute('aria-valuemax',limits.max);handle.setAttribute('aria-valuenow',width);handle.setAttribute('aria-valuetext',width+' pixels');return width;}
function setSidebarWidth(width,persist=true){if(!Number.isFinite(width))return;const limits=sidebarLimits(viewportWidth());state.sidebarWidth=Math.round(Math.max(limits.min,Math.min(limits.max,width)));applySidebarWidth();if(persist)saveLocal();}
function resetSidebarWidth(){state.sidebarWidth=null;applySidebarWidth();saveLocal();}
const resizeHandle=$('sidebar-resize');
resizeHandle.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();event.stopPropagation();cancelViewMotion();state.sidebarResize={pointerId:event.pointerId,startX:event.clientX,width:applySidebarWidth()};document.documentElement.dataset.sidebarResizing='true';resizeHandle.setPointerCapture(event.pointerId);});
resizeHandle.addEventListener('pointermove',event=>{const drag=state.sidebarResize;if(!drag||event.pointerId!==drag.pointerId)return;setSidebarWidth(drag.width+event.clientX-drag.startX,false);});
function finishSidebarResize(){if(!state.sidebarResize)return;state.sidebarResize=null;document.documentElement.dataset.sidebarResizing='false';saveLocal();setView(state.view);}
resizeHandle.addEventListener('pointerup',finishSidebarResize);
resizeHandle.addEventListener('pointercancel',finishSidebarResize);
resizeHandle.addEventListener('lostpointercapture',finishSidebarResize);
resizeHandle.addEventListener('dblclick',resetSidebarWidth);
resizeHandle.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End','Enter'].includes(event.key))return;event.preventDefault();const current=applySidebarWidth(),limits=sidebarLimits(viewportWidth());if(event.key==='Enter')resetSidebarWidth();else setSidebarWidth(event.key==='Home'?limits.min:event.key==='End'?limits.max:current+(event.key==='ArrowLeft'?-1:1)*(event.shiftKey?40:20));});
if(typeof window!=='undefined')window.addEventListener('resize',applySidebarWidth);

if(typeof ResizeObserver==='function')new ResizeObserver(()=>{if(activeSession()&&!state.drag)focusRiver();else setView(state.view);}).observe(atlas);
if(typeof window!=='undefined')window.addEventListener('storage',event=>{if((event.key!==KEY&&!event.key?.startsWith(MappingStorage.prefix))||!event.newValue||activeSession())return;loadLocal();for(const [id,values] of Object.entries(state.originals)){const r=editableRecord(id);if(r)Object.assign(r,values);}applyStoredEdits();renderSidebar();renderMap();announce('Mapping backup updated in this browser.');});
async function boot(){loadLocal();try{const response=await fetch('./data/rivers.json',{cache:'no-cache'});if(!response.ok)throw new Error('Map data could not load.');const data=await response.json();state.rivers=data.rivers;state.places=data.places||[];state.worldPlaces=data.worldPlaces||[];state.states=data.states||[];state.land=data.land;state.worldLand=data.worldLand||[];state.cities=data.cities||[];captureOriginals();applyStoredEdits();state.indiaSidebar=true;updateWorldLayout();renderSidebar();renderMap();}catch(error){$("sidebar-content").innerHTML='<div class="empty session-error">The India atlas could not load. Reload Mapping to try again.</div>';$("map-subtitle").textContent=error.message;}}


// Optional reference lines share the map projection and never capture map clicks.
function latitudeLines(){const project=state.scope==='world'?worldXY:xy,start=state.scope==='world'?-180:61,end=state.scope==='world'?180:102;return [['Equator',0],['Tropic of Cancer',23.436],['Tropic of Capricorn',-23.436]].map(([name,lat])=>({name,lat,start:project([start,lat]),end:project([end,lat])}));}
function renderLatitudes(){const layer=$('latitude-lines');if(!state.latitudes){layer.innerHTML='';return;}const scale=markerScale();layer.innerHTML=latitudeLines().map(line=>{const [x,y]=line.start,end=line.end[0],labelX=Math.max(x+8*scale,Math.min(end-145*scale,state.view.x+14*scale));return '<g class="latitude-guide"><path d="M'+x+' '+y+'H'+end+'"/><text x="'+labelX+'" y="'+(y-5*scale)+'" font-size="'+11*scale+'">'+line.name+' · '+Math.abs(line.lat)+(line.lat>0?'° N':line.lat<0?'° S':'°')+'</text></g>';}).join('');}
document.addEventListener('change',e=>{if(e.target.id==='important-latitudes'){state.latitudes=e.target.checked;renderLatitudes();saveLocal();}});

boot();
